var all=[].slice.call(body.rows);function val(r,i){return(r.cells[i]?r.cells[i].textContent:'').trim()}function numv(x){var m=x.replace(/[,\\s]|BDT/g,'');return/^[-+]?\\d+(\\.\\d+)?$/.test(m)?parseFloat(m):null}
