function shell(u, active, body, msg) {
  const adm = u.is_admin;
  const tabs = [['/', 'Home'], ['/id', 'My ID'], ['/pay', 'Pay'], ['/payments', 'Receipts'], ['/ledger', 'Statement'], ['/notices', 'Notices'], ['/password', 'Password']];
  const atabs = [['/admin', 'Dashboard'], ['/admin/members', 'Members'], ['/admin/payments', 'Payments'], ['/admin/notices', 'Notices']];
  const isAdminView = adm && (active.startsWith('/admin') || u.id === 'admin');
  const set = isAdminView ? (u.id === 'admin' ? atabs.concat([['/password', 'Password']]) : atabs) : tabs;
  let app = '', css = '';
  if (!isAdminView) {
    const titles = { '/': 'Home', '/id': 'My ID', '/pay': 'Pay', '/payments': 'Receipts', '/ledger': 'Statement', '/notices': 'Notices', '/password': 'Password' };
    const first = String(u.name_en || '').split(' ')[0];
    const main = [['/', 'Home', 'home'], ['/id', 'My ID', 'id'], ['/pay', 'Pay', 'pay'], ['/payments', 'Receipts', 'rec']];
    const inMore = ['/ledger', '/notices', '/password', '/investments', '/loans'].includes(active);
    css = APPCSS;
    app = `<div class="appbar"><div class="r1"><div class="lg"><img src="https://rbdf.org/logo.png" alt="RBDF"></div>${av(u.id, 38)}</div><div class="ti">${active === '/' ? 'Hello, ' + e(first) : e(titles[active] || 'Portal')}</div><div class="su">${active === '/' ? 'Welcome to your Forum portal' : e(u.name_en) + ' · ' + e(u.id)}</div></div>`;
    app += `<nav class="bnav" aria-label="App">${main.map(([h, l, k]) => `<a href="${h}" class="${active === h ? 'on' : ''}"><span class="pill">${ico(k)}</span>${l}</a>`).join('')}<button type="button" id="mbtn" class="${inMore ? 'on' : ''}"><span class="pill">${ico('more')}</span>More</button></nav><div class="sheetbg" id="sbg"></div><div class="sheet" id="sht"><div class="gr"></div><a href="/ledger"><span class="ic">${ico('list')}</span>Statement</a><a href="/investments"><span class="ic">${ico('chart')}</span>My investments</a><a href="/loans"><span class="ic">${ico('cash')}</span>My loans</a><a href="/notices"><span class="ic">${ico('bell')}</span>Notices</a><a href="/password"><span class="ic">${ico('lock')}</span>Change password</a>${isStaff(u) && u.id !== 'admin' ? `<a href="/admin"><span class="ic">${ico('shield')}</span>Admin panel</a>` : ''}<form method="post" action="/logout" style="margin:0"><button><span class="ic" style="background:#FDE7E5;color:#9B2C22">${ico('out')}</span>Logout</button></form></div><script>(function(){var b=document.getElementById('mbtn'),s=document.getElementById('sht'),g=document.getElementById('sbg');function t(x){s.classList.toggle('on',x);g.classList.toggle('on',x)}b.onclick=function(){t(true)};g.onclick=function(){t(false)}})()</script>`;
  }
  return page('Portal', `${css}<header class="top"><div class="wrap"><img src="https://rbdf.org/logo.png" alt="RBF" style="height:38px"><nav style="flex:1;display:flex;flex-wrap:wrap;gap:4px">${set.map(([h, l]) => `<a href="${h}" class="${active === h ? 'on' : ''}">${l}</a>`).join('')}${isStaff(u) && u.id !== 'admin' ? '<a href="/admin">Admin panel</a>' : ''}</nav><span class="mut">${e(u.name_en)} · ${e(u.id)}</span><form method="post" action="/logout"><button class="btn o s">Logout</button></form></div></header>${app}<main class="wrap" style="padding:26px 20px 60px">${msg ? `<div class="msg ${msg.startsWith('!') ? 'err' : ''}">${e(msg.replace(/^!/, ''))}</div>` : ''}${body}</main>`);
}

// ---- request plumbing
const fails = new Map();
function body(req) { return new Promise((res, rej) => { let b = ''; req.on('data', c => { b += c; if (b.length > 30000) { rej(new Error('big')); req.destroy(); } }); req.on('end', () => res(Object.fromEntries(new URLSearchParams(b)))); }); }
function send(res, code, html, extra = {}) {
  if (ADMHOST && typeof html === 'string') html = html.replace(/<script>if\('serviceWorker'[\s\S]*?<\/script>/, ''); res.writeHead(code, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff', 'X-Frame-Options': 'DENY', 'Referrer-Policy': 'same-origin', 'Strict-Transport-Security': 'max-age=31536000', ...extra }); res.end(html); }
const redirect = (res, to, extra = {}) => { res.writeHead(303, { Location: to, ...extra }); res.end(); };
