const bnMonth = ym0 => { const m = /^(\d{4})-(\d{2})/.exec(ym0 || ''); return m ? BNM[parseInt(m[2]) - 1] + ' ' + bn(m[1]) : ''; };
const bnDate = d => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(d || ''); return m ? bn(parseInt(m[3])) + ' ' + BNM[parseInt(m[2]) - 1] + ' ' + bn(m[1]) : (d || ''); };
