function ashell(u, active, title, subtitle, body, msg) {
  const nav = NAVG.map(([g, it]) => `<div class="g"><h6>${g}</h6>` + it.map(([l, h, k]) => `<a href="${h}" class="${active === h ? 'on' : ''}">${ico(k)}<span>${l.replace(/&/g, '&amp;')}</span></a>`).join('') + '</div>').join('');
  return page(title, `<style>${ACSS}</style><div class="al"><aside class="side"><img src="https://rbdf.org/logo.png" alt="RBF" style="width:200px;max-width:100%;height:auto;margin:4px 14px 14px;display:block">${nav}<div class="g"><h6>Account</h6><a href="/password">${ico('lock')}<span>Change password</span></a><form method="post" action="/logout"><button class="btn o s" style="margin:10px 14px">Logout</button></form></div></aside><script>(function(){var s=document.querySelector('.side');if(!s)return;try{var y=sessionStorage.getItem('sbY'),x=sessionStorage.getItem('sbX');if(y!==null){s.scrollTop=+y;s.scrollLeft=+(x||0)}else{var a=s.querySelector('a.on');if(a&&a.scrollIntoView)a.scrollIntoView({block:'center',inline:'center'})}}catch(e){}s.addEventListener('scroll',function(){try{sessionStorage.setItem('sbY',s.scrollTop);sessionStorage.setItem('sbX',s.scrollLeft)}catch(e){}})})()</script><main class="am">${msg ? `<div class="msg ${msg.startsWith('!') ? 'err' : ''}">${e(msg.replace(/^!/, ''))}</div>` : ''}<h1 style="margin:0 0 4px;font-size:26px">${e(title)}</h1><p class="sub">${subtitle || ''}</p>${body}<p class="mut" style="margin-top:30px">Signed in as ${e(u.name_en)} (${e(u.id)}) · ${e(u.role)}</p></main></div><script>${SPA_JS}</script>`);
}
const tbl = (cols, rows, empty) => rows.length ? `<div class="card scroll"><table><tr>${cols.map(c => `<th>${c}</th>`).join('')}</tr>${rows.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join('')}</tr>`).join('')}</table></div>` : `<div class="card mut">${empty || 'Nothing here yet.'}</div>`;
const stTag = s => { const k = String(s).toLowerCase(); return `<span class="tag ${/valid|approved|active|paid|success|sent|delivered|running|closed|verified|matched|upcoming|done/.test(k) ? '' : /pending|queued|waiting|due|planned|open/.test(k) ? 'w' : /reject|cancel|fail|missing|deceased|suspend/.test(k) ? 'x' : 'g'}">${e(s)}</span>`; };
const hid = o => Object.entries(o).map(([k, v]) => `<input type="hidden" name="${k}" value="${e(v)}">`).join('');
const pf = (act, extra = {}, label, cls = 'btn s', attrs = '') => `<form method="post" style="display:inline" ${attrs}>${hid({ act, ...extra })}<button class="${cls}">${label}</button></form>`;
const csvCell = v => '"' + String(v ?? '').replace(/<[^>]*>/g, '').replace(/"/g, '""') + '"';
const strip = s => String(s).replace(/<[^>]*>/g, '');
const REPORTS = [['member', 'Member report', 'All members with status and contact'], ['collection', 'Collection report', 'Money received by date, type and method'], ['due', 'Due report', 'Who owes what, with aging'], ['share', 'Share report', 'Shares by member and share capital'], ['monthly', 'Monthly report', 'Income, expense and collection for a month'], ['annual', 'Annual report', 'Full-year summary for the general meeting'], ['expense', 'Expense report', 'Spending by head and approver'], ['bank', 'Bank report', 'Bank account balances and movements'], ['cash', 'Cash report', 'Cash in hand and daily cash book'], ['ledger', 'Member ledger', 'Every entry of one member'],
  ['gl', 'General Ledger', 'All ledger entries'], ['cashbook', 'Cash Book', 'Cash in hand register'], ['bankbook', 'Bank Book', 'Bank and mobile banking registers'], ['income', 'Income Report', 'Receipts by category'], ['trial', 'Trial Balance', 'Debit equals credit'], ['incstmt', 'Income Statement', 'Income, expense, surplus'], ['bs', 'Balance Sheet', 'Assets, liabilities and equity'], ['cashflow', 'Cash Flow', 'Money in and out'], ['mcoll', 'Monthly Collection Report', 'Collected per month'], ['outstanding', 'Outstanding Due Report', 'Open dues by member']];
function mkReport(r, from, to, mid) {
  from = from || '2000-01-01'; to = to || '2999-12-31';
  const P = q("SELECT p.*, m.name_en FROM payments p JOIN members m ON m.id=p.member_id WHERE p.status='valid' AND p.paid_on BETWEEN ? AND ? ORDER BY p.paid_on, p.seq", from, to);
  const E = q("SELECT * FROM expenses WHERE status='paid' AND date BETWEEN ? AND ? ORDER BY date", from, to);
  const sum = a => a.reduce((s, x) => s + x.amount, 0);
  const T = (title, cols, rows) => ({ title, cols, rows });
  switch (r) {
    case 'member': return T('Member report', ['ID', 'Name', 'Role', 'Mobile', 'Shares', 'Status'], q("SELECT * FROM members WHERE id!='admin' ORDER BY seq").map(m => [m.id, m.name_en, m.role, m.mobile, m.shares, m.status]));
    case 'collection': case 'income': { const by = {}; P.forEach(p => { by[p.kind] = (by[p.kind] || 0) + p.amount; }); return r === 'income' ? T('Income report', ['Category', 'Amount (BDT)'], Object.entries(by).map(([k, v]) => [k, num(v)]).concat([['Total', num(sum(P))]])) : T('Collection report', ['Receipt', 'Date', 'Member', 'Type', 'Method', 'Amount (BDT)'], P.map(p => [p.no, p.paid_on, p.member_id + ' ' + p.name_en, p.kind, p.method || '', num(p.amount)]).concat([['Total', '', '', '', '', num(sum(P))]])); }
    case 'due': case 'outstanding': { const rows = allDue().filter(d => d.total > 0).map(d => [d.id, mname(d.id), num(d.total), d.open.length ? Math.max(...d.open.map(x => x.days)) + ' days' : '']); return T(r === 'due' ? 'Due report' : 'Outstanding due report', ['Member', 'Name', 'Due (BDT)', 'Oldest due'], rows.concat([['Total', '', num(allDue().reduce((s, d) => s + d.total, 0)), '']])); }
    case 'share': { const ms = q("SELECT * FROM members WHERE id!='admin' ORDER BY seq"); const c = cfg(); return T('Share report', ['ID', 'Name', 'Shares', 'Share capital (BDT)'], ms.map(m => [m.id, m.name_en, m.shares, num(m.shares * c.share_price)]).concat([['Total', '', ms.reduce((s, m) => s + m.shares, 0), num(ms.reduce((s, m) => s + m.shares, 0) * c.share_price)]])); }
    case 'monthly': case 'annual': case 'incstmt': { const inc = sum(P), exp = sum(E); const by = {}; E.forEach(x => { by[x.head] = (by[x.head] || 0) + x.amount; }); return T(r === 'annual' ? 'Annual report' : r === 'incstmt' ? 'Income statement' : 'Monthly report', ['Item', 'Amount (BDT)'], [['Income (collections)', num(inc)], ['Expenses', num(exp)], ...Object.entries(by).map(([k, v]) => ['  · ' + k, num(v)]), ['Surplus / Deficit', num(inc - exp)], ['Payments received (count)', P.length]]); }
    case 'expense': return T('Expense report', ['Voucher', 'Date', 'Head', 'Paid to', 'Requested by', 'Approved by', 'Amount (BDT)'], E.map(x => [x.voucher, x.date, x.head, x.paid_to, x.requested_by, x.approved_by, num(x.amount)]).concat([['Total', '', '', '', '', '', num(sum(E))]]));
    case 'bank': case 'cash': case 'cashbook': case 'bankbook': { const names = r === 'cash' || r === 'cashbook' ? ['Cash in Hand'] : ['Bank Account 01', 'bKash Merchant', 'Nagad']; const rows = []; names.forEach(n => { const a = q1('SELECT * FROM accounts WHERE name=?', n); let bal = a.opening; rows.push([n, 'Opening', '', '', '', num(bal)]); q('SELECT * FROM acc_txn WHERE account_id=? AND date BETWEEN ? AND ? ORDER BY date,id', a.id, from, to).forEach(t => { const inn = ['receipt', 'deposit', 'transfer_in'].includes(t.kind); bal += inn ? t.amount : -t.amount; rows.push([n, t.date, t.kind, t.ref || t.note || '', (inn ? '+' : '-') + num(t.amount), num(bal)]); }); }); return T(r === 'bank' ? 'Bank report' : r === 'cash' ? 'Cash report' : r === 'cashbook' ? 'Cash book' : 'Bank book', ['Account', 'Date', 'Type', 'Reference', 'Amount', 'Balance'], rows); }
    case 'ledger': case 'gl': { const rows = q(`SELECT * FROM ledger WHERE ${r === 'ledger' ? 'member_id=? AND' : "? IS NOT NULL AND"} date BETWEEN ? AND ? ORDER BY date,id`, r === 'ledger' ? mid || '' : '1', from, to); let bal = 0; return T(r === 'ledger' ? 'Member ledger ' + (mid || '') : 'General ledger', ['Date', 'Member', 'Reference', 'Description', 'Debit', 'Credit', 'Balance'], rows.map(l => { bal += l.debit - l.credit; return [l.date, l.member_id, l.ref, l.descr, l.debit ? num(l.debit) : '–', l.credit ? num(l.credit) : '–', num(Math.abs(bal)) + (bal >= 0 ? ' Dr' : ' Cr')]; })); }
    case 'trial': case 'bs': { const ab = accBal(); const funds = ab.reduce((s, a) => s + a.close, 0); const dueT = allDue().reduce((s, d) => s + d.total, 0); const rec = q1("SELECT COALESCE(SUM(credit),0) c FROM ledger WHERE kind='payment'").c; const loansOut = q1('SELECT COALESCE(SUM(amount-paid),0) c FROM loan_inst').c; if (r === 'trial') { const rows = ab.map(a => [a.name, num(a.close), '']).concat([['Members receivable (dues)', num(dueT), ''], ['Member contributions', '', num(rec + dueT - dueT)], ['Retained surplus / (deficit)', '', num(funds + dueT - rec)]]); return T('Trial balance', ['Account', 'Debit', 'Credit'], rows.concat([['Total', num(funds + dueT), num(funds + dueT)]])); } return T('Balance sheet', ['Item', 'Amount (BDT)'], [['Cash and bank', num(funds)], ['Dues receivable', num(dueT)], ['Loans outstanding', num(loansOut)], ['Total assets', num(funds + dueT + loansOut)], ['Member funds (contributions)', num(rec)], ['Reserves / surplus', num(funds + dueT + loansOut - rec)], ['Total liabilities and equity', num(funds + dueT + loansOut)]]); }
    case 'cashflow': { const inn = q1("SELECT COALESCE(SUM(amount),0) c FROM acc_txn WHERE kind IN ('receipt','deposit') AND date BETWEEN ? AND ?", from, to).c, out = q1("SELECT COALESCE(SUM(amount),0) c FROM acc_txn WHERE kind IN ('payment','withdraw','charge') AND date BETWEEN ? AND ?", from, to).c; return T('Cash flow', ['Item', 'Amount (BDT)'], [['Money in', num(inn)], ['Money out', num(out)], ['Net', num(inn - out)]]); }
    case 'mcoll': { const by = {}; P.forEach(p => { by[ym(p.paid_on)] = (by[ym(p.paid_on)] || 0) + p.amount; }); return T('Monthly collection report', ['Month', 'Collected (BDT)'], Object.entries(by).map(([k, v]) => [k, num(v)])); }
  }
  return T('Report', ['Info'], [['Unknown report']]);
}
function reportOut(res, rep, fmt, meta) {
  if (fmt === 'csv') { const body = '﻿' + [rep.cols, ...rep.rows].map(r => r.map(csvCell).join(',')).join('\r\n'); res.writeHead(200, { 'Content-Type': 'text/csv; charset=utf-8', 'Content-Disposition': `attachment; filename="${rep.title.replace(/\W+/g, '_')}.csv"` }); return res.end(body); }
  const body = padWrap(`<h2 style="margin:0 0 4px">${e(rep.title)}</h2><div class="mut">${e(meta)}</div><div style="margin-top:12px"><table><tr>${rep.cols.map(c => `<th>${e(c)}</th>`).join('')}</tr>${rep.rows.map(r => `<tr>${r.map(c => `<td>${e(c)}</td>`).join('')}</tr>`).join('')}</table></div>`, fmtD(today()));
  send(res, 200, page(rep.title, body));
}

