    const LISTS = [['cats', 'Payment categories', 'Types shown when collecting'], ['methods', 'Payment methods', 'Cash, bank, mobile banking'], ['heads', 'Expense heads', 'Used for expense requests'], ['statuses', 'Member statuses', 'Members are never deleted'], ['roles', 'Roles', 'Who can do what'], ['modules', 'Modules', 'Switch on or off as needed']];
